import{c as e,Q as a,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const b=JSON.parse('{"title":"AI 原生工程組織管理指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/35-ai-native-engineering.md","filePath":"research/best-practices/35-ai-native-engineering.md","lastUpdated":1780842316000}'),d={name:"research/best-practices/35-ai-native-engineering.md"};function o(n,t,l,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-原生工程組織管理指南" tabindex="-1">AI 原生工程組織管理指南 <a class="header-anchor" href="#ai-原生工程組織管理指南" aria-label="Permalink to &quot;AI 原生工程組織管理指南&quot;">​</a></h1><blockquote><p>來源：<a href="https://claude.com/blog/running-an-ai-native-engineering-org" target="_blank" rel="noreferrer">Running an AI-native engineering org</a>（2026-06-03）<br> 作者：Fiona Fung（Claude Code &amp; Claude Cowork Engineering Director）<br> 整理日期：2026-06-05</p></blockquote><hr><h2 id="核心主張" tabindex="-1">核心主張 <a class="header-anchor" href="#核心主張" aria-label="Permalink to &quot;核心主張&quot;">​</a></h2><p>當 Agentic coding 成為預設工作方式，工程組織必須根本性地重組流程。瓶頸從<strong>撰寫程式碼</strong>轉移到<strong>驗證、審查、安全性</strong>，需要在規劃、Context 蒐集、Code Review、團隊組成上建立新規範。</p><hr><h2 id="四大流程轉變" tabindex="-1">四大流程轉變 <a class="header-anchor" href="#四大流程轉變" aria-label="Permalink to &quot;四大流程轉變&quot;">​</a></h2><h3 id="_1-規劃轉型-jit-planning" tabindex="-1">1. 規劃轉型：JIT Planning <a class="header-anchor" href="#_1-規劃轉型-jit-planning" aria-label="Permalink to &quot;1. 規劃轉型：JIT Planning&quot;">​</a></h3><p>傳統六個月 Roadmap 已過時。Claude Code 團隊採用「即時規劃（JIT Planning）」：</p><ul><li>設計文件 → 原型驅動開發</li><li>快速內部用戶回饋循環（而非長期前期規劃）</li><li>每次模型發布重新評估現有功能</li></ul><h3 id="_2-context-蒐集轉移" tabindex="-1">2. Context 蒐集轉移 <a class="header-anchor" href="#_2-context-蒐集轉移" aria-label="Permalink to &quot;2. Context 蒐集轉移&quot;">​</a></h3><table tabindex="0"><thead><tr><th>舊方式</th><th>新方式</th></tr></thead><tbody><tr><td>找原始程式碼作者</td><td>先問 Claude contextual questions</td></tr><tr><td>手動彙整客戶回饋</td><td>持續背景流程自動化</td></tr></tbody></table><h3 id="_3-code-review-重新定義" tabindex="-1">3. Code Review 重新定義 <a class="header-anchor" href="#_3-code-review-重新定義" aria-label="Permalink to &quot;3. Code Review 重新定義&quot;">​</a></h3><p>Claude 處理：style、linting、bug 偵測、test 生成</p><p>人工 Review 聚焦：</p><ul><li>法律 review</li><li>安全敏感程式碼</li><li>產品感（Product sense）</li><li>設計品味</li></ul><h3 id="_4-角色模糊化" tabindex="-1">4. 角色模糊化 <a class="header-anchor" href="#_4-角色模糊化" aria-label="Permalink to &quot;4. 角色模糊化&quot;">​</a></h3><ul><li>PM 現在也寫程式</li><li>工程師承擔設計和內容工作</li><li>招聘優先「有產品感的創意建造者」和深度系統專家，而非純粹編碼產出</li></ul><hr><h2 id="三大團隊原則" tabindex="-1">三大團隊原則 <a class="header-anchor" href="#三大團隊原則" aria-label="Permalink to &quot;三大團隊原則&quot;">​</a></h2><ol><li><strong>無情地 Dogfood 自己的產品</strong>：每位成員使用 Claude Code 和 Claude Cowork</li><li><strong>保持扁平結構</strong>：Manager 從 IC 起步；扁平結構支援敏捷性</li><li><strong>消滅過時流程</strong>：團隊成員有明確授權質疑並消除無效工作流</li></ol><hr><h2 id="三個關鍵指標" tabindex="-1">三個關鍵指標 <a class="header-anchor" href="#三個關鍵指標" aria-label="Permalink to &quot;三個關鍵指標&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指標</th><th>說明</th><th>目標</th></tr></thead><tbody><tr><td><strong>Onboarding ramp time</strong></td><td>工程師第一週就 ship 真實程式碼</td><td>≤ 1 週</td></tr><tr><td><strong>PR cycle time</strong></td><td>識別 build system 和 CI 瓶頸</td><td>持續縮短</td></tr><tr><td><strong>Claude-assisted commits</strong></td><td>預設接近 100%</td><td>≈ 100%</td></tr></tbody></table><p>Claude Code 團隊連續四個月沒有觀察到非 Claude 協助的 commit。</p><hr><h2 id="如何開始" tabindex="-1">如何開始 <a class="header-anchor" href="#如何開始" aria-label="Permalink to &quot;如何開始&quot;">​</a></h2><p>找到你的「最吵工作流（Noisiest Workflow）」——最昂貴、最讓人頭痛、最低效的流程：</p><ol><li>問「這個流程現在還在發揮作用嗎？」</li><li>判斷是否可以自動化或直接消除</li></ol><p><strong>實例（Fung 的經驗）：</strong><br> 一個有眾多與會者的週例行狀態會議——除了報告自己狀態外，每個人都在滑電腦。問「我們為什麼要開這個會？」→ 取消會議，釋放大量團隊時間。</p><hr><h2 id="ai-原生-vs-傳統工程文化對比" tabindex="-1">AI 原生 vs 傳統工程文化對比 <a class="header-anchor" href="#ai-原生-vs-傳統工程文化對比" aria-label="Permalink to &quot;AI 原生 vs 傳統工程文化對比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面向</th><th>傳統</th><th>AI 原生</th></tr></thead><tbody><tr><td>規劃</td><td>季度/年度 Roadmap</td><td>JIT，原型驅動</td></tr><tr><td>Context</td><td>找人問</td><td>先問 Claude</td></tr><tr><td>Code Review</td><td>覆蓋 style + logic</td><td>人工聚焦高判斷領域</td></tr><tr><td>角色邊界</td><td>明確分工</td><td>模糊，PM/設計/工程互滲</td></tr><tr><td>招聘</td><td>編碼吞吐量</td><td>產品感 + 系統思維</td></tr><tr><td>流程</td><td>固化規範</td><td>主動質疑並消除</td></tr></tbody></table><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>17-best-practices-overview.md</code> — 官方最佳實踐總綱</li><li><code>04-subagent-mcp-skill.md</code> — Sub-Agent 委派策略</li><li><code>29-onboarding-large-codebase.md</code> — 大型 Codebase 入職實踐</li></ul>',36)])])}const g=e(d,[["render",o]]);export{b as __pageData,g as default};
